/**
 * AUTO-GENERATED by /audit-prove — persistence verification (DIRECT DB mode).
 * Copy to <testDir>/db-verify.ts, fill the {{...}} placeholders, then run with the
 * project's runner (from project.json `db.runner`), e.g.:
 *   bun e2e/db-verify.ts --checks <session>/test/db-checks.json --out <session>/test/db-results.json
 *   # or, for a non-bun project:  npx tsx e2e/db-verify.ts --checks ... --out ...
 *
 * It REUSES THE PROJECT'S OWN DB client/helper so it inherits the project's driver,
 * schema, and (for multi-tenant) tenant routing — do NOT hand-roll a connection.
 * Emits db-results.json: [{ id, status: "pass"|"fail", detail }]. Exit 3 on any fail.
 *
 * Each check in db-checks.json (authored in Phase 2 from the audit's `persistence`
 * notes — the table + key columns each write must produce):
 *   { "id": "F-stock-decrement", "tenant": "<orgId|null>", "table": "products",
 *     "where": { "id": "<uuid>" }, "expect": { "stock": 9 } }
 * - "where" selects the row(s); "expect" asserts column == value.
 * - omit "expect" and set "count" to assert a row count (existence: "count": 1).
 */
import { readFileSync, writeFileSync } from "node:fs";
import { sql } from "drizzle-orm"; // adjust if the project uses a different query builder
// {{DB_HELPER_IMPORT}}  e.g.:
// import { loadDevVars, createTenantDb, createControlPanelDb } from "../apps/server/src/tests/helpers/integration-setup";

const arg = (n: string, d: string | null = null) => {
	const i = process.argv.indexOf(`--${n}`);
	return i >= 0 && process.argv[i + 1] ? process.argv[i + 1] : d;
};
const checksPath = arg("checks");
const outPath = arg("out");
if (!checksPath) throw new Error("--checks <db-checks.json> is required");

type Check = {
	id: string;
	tenant?: string | null;
	table: string;
	where: Record<string, unknown>;
	expect?: Record<string, unknown>;
	count?: number;
};
const checks: Check[] = JSON.parse(readFileSync(checksPath, "utf8"));

// {{RESOLVE_DB}} — return a Drizzle client for the given tenant (or the single DB).
// Multi-tenant: resolve the tenant Neon branch by orgId via the project helper.
async function resolveDb(_tenant: string | null | undefined) {
	// e.g.:  const vars = await loadDevVars();
	//        return _tenant ? await createTenantDb(vars, _tenant) : createControlPanelDb(vars);
	throw new Error("RESOLVE_DB not implemented — wire the project's DB helper here");
}

const ident = (s: string) => `"${String(s).replace(/"/g, '""')}"`; // quote a SQL identifier
const results: { id: string; status: "pass" | "fail"; detail: string }[] = [];

for (const c of checks) {
	try {
		const db = await resolveDb(c.tenant);
		const cols = Object.keys(c.where ?? {});
		const whereSql = cols.length
			? sql.join(
					cols.map((k) => sql`${sql.raw(ident(k))} = ${c.where[k]}`),
					sql` AND `,
				)
			: sql`true`;
		const res = (await db.execute(
			sql`SELECT * FROM ${sql.raw(ident(c.table))} WHERE ${whereSql} LIMIT 50`,
		)) as unknown as { rows?: Record<string, unknown>[] } | Record<string, unknown>[];
		const rows = Array.isArray(res) ? res : (res.rows ?? []);

		if (typeof c.count === "number") {
			results.push(
				rows.length === c.count
					? { id: c.id, status: "pass", detail: `count=${rows.length}` }
					: { id: c.id, status: "fail", detail: `expected count ${c.count}, got ${rows.length}` },
			);
			continue;
		}
		if (rows.length === 0) {
			results.push({ id: c.id, status: "fail", detail: "no matching row persisted" });
			continue;
		}
		const row = rows[0];
		const mismatches = Object.entries(c.expect ?? {}).filter(([k, v]) => String(row[k]) !== String(v));
		results.push(
			mismatches.length
				? {
						id: c.id,
						status: "fail",
						detail: mismatches.map(([k, v]) => `${k}: expected ${v}, got ${row[k]}`).join("; "),
					}
				: { id: c.id, status: "pass", detail: "row matches expected" },
		);
	} catch (e) {
		results.push({ id: c.id, status: "fail", detail: `verify error: ${(e as Error).message}` });
	}
}

const json = JSON.stringify(results, null, 2);
if (outPath) writeFileSync(outPath, json);
process.stdout.write(`${json}\n`);
const failed = results.filter((r) => r.status === "fail").length;
console.error(`[db-verify] ${results.length - failed} pass / ${failed} fail`);
process.exit(failed ? 3 : 0);
